local D = LegionChineseDB
D.Quests[47746]={Title="躲藏好",Objectives="找到一把翻新的军用步枪、初级布绷带和腌制鹿肉干。",Description="你……你看见了吗？阿尔萨斯王子刚刚把那个人杀了！真残忍！就在大街上！$b$b<梅丽娜恢复了镇静。>$b$b我得保护孩子们。请你们帮帮我，外来者。我需要一把枪、绷带、还有一些鹿肉干。$b$b孩子们！大家都进屋去！"}
D.Quests[47747]={Title="以火攻毒",Objectives="找到一个燧石点火器和一段沉重的草绳。",Description="我还有最后一个要求，陌生人。我看到外面的情景了，我也听说过这场“瘟疫”的事情。我不想不经反抗就束手待毙。$b$b我的酒吧后面有很多朗姆酒，足够把整个酒馆点燃，但我没有能让我安全放火的工具。帮我找一块燧石和一段绳子，我就把斯坦索姆小巷的钥匙给你。"}
D.Quests[47750]={Title="给埃姆雷",Objectives="把腌制鹿肉干交给埃姆雷·尼尔。",Description="不过，我们这里食物很充足。如果你有胆量上街，请把这些鹿肉交给酒馆里那个傻瓜。$b$b告诉他，是孩子们给他的。"}
D.Quests[47754]={Title="轻度烧烤",Objectives="使用圣光裁决者摧毁挡住泽尼达尔入口的石堆。",Description="$n，能听到我说话吗？很好。$b$b圣光裁决者已经安装到维迪卡尔上了。我们应该马上就能使用它的力量。$b$b我们可以用它来清理挡住泽尼达尔的石堆，还能消灭敌人。$b$b对待任何新技术，我们都得先测试一下。要全面测试。我相信那里有足够多的目标。"}
D.Quests[47771]={Title="找到“神射手”的下落",Objectives="找到“神射手”巴拉特。",Description="想要解救泽拉，我们得需要更大的炮。$b$b炮就在靠近泽尼达尔的那些摧毁的碉堡里。如果是巴拉特在跟进这项任务，他肯定已经开始调查这片区域了。也许他已经找到了飞船的主炮。$b$b如果你去那边，请确保他还活着，好吗？"}
D.Quests[47772]={Title="炮火蔽日",Objectives="破坏部落攻城火炮。",Description="哦！是我！你是$n，对吧？我记得这里！$b$b我好像被困在部落和联盟的战斗之中，一般来说，这不是什么大事，只不过每当我想飞走，那台大炮似乎就瞄准我不放。$b$b你能帮我解决掉它吗？"}
D.Quests[47773]={Title="炮火蔽日",Objectives="破坏联盟攻城火炮。",Description="哦！是我！你是$n，对吧？我记得这里！$b$b我好像被困在部落和联盟的战斗之中，一般来说，这不是什么大事，只不过每当我想飞走，那台大炮似乎就瞄准我不放。$b$b你能帮我解决掉它吗？"}
D.Quests[47790]={Title="动荡的能量",Description="原本限制在暗夜井中的能量一经释放……便导致破碎群岛各地阿曼苏尔遗留下的影响力变得错综复杂。很遗憾，我之前的研究成果已经无效，正如同这个瓶子里的东西一样。$b$b我必须弄清楚这些变化的起因！拜托了，请你给我多带来一些样本，让我继续研究。无需多言，一旦我的研究获得突破性进展，你也会跟着获利。"}
D.Quests[47791]={Title="动荡的能量",Description="阿曼苏尔的能量变得越来越不稳定，这非常令人不安。我们必须进一步调查这个问题。$b$b是军团的腐化导致它变得不稳定吗？不，这个因素出现太晚，不足以造成影响。肯定是别的什么东西……$b$b<维迪尔非常心不在焉，说到一半就停住了，也没有正面看着你。>"}
D.Quests[47793]={Title="变质的样品",Objectives="前往破碎群岛的达拉然，把变质的样品交给奥法工匠维迪尔。",Description="<你捡起一瓶粘稠的漆黑液体。里面的东西对你的触摸起了反应，它沸腾起来，疯狂地冒着气泡，然后又迅速平静下来，发出持久不灭的光。在这个状态下，这种物质看起来很像魔力酒，但刚才的反应让你想起分解抑魔金的过程。$b$b你把瓶子放进背包。达拉然城里某个熟悉抑魔金熔炉的人可能了解得更多。>"}
D.Quests[47807]={Title="我担心我的朋友",Objectives="在黑曜石巨龙圣地杀死佐拉赛德。",Description="我听说，黑龙的巨龙圣地出了点麻烦。我知道，我是青铜龙，不过那又如何！我偶尔也会担心他们！他们的脾气也不总是那么暴躁。$b$b如果你正好要过去的话，你能不能处理一下……在那边引发混乱的东西？"}
D.Quests[47808]={Title="行尸走肉",Objectives="在红玉巨龙圣地击杀塔拉·冰寒。",Description="你好，$r。我知道你来这里是要帮青铜龙，但我也要请你做一件事。$b$b红玉巨龙圣地被亡灵占领了。我的圣地守护者们没有准备，如果没有人尽快去帮助，我很可能会失去他们。你愿意帮我们吗？"}
D.Quests[47809]={Title="魔网中的黑暗",Objectives="在碧蓝巨龙圣地杀死虚空巨怪。",Description="在我族群的巨龙圣地，有一股奇异而黑暗的能量正在扰乱那里的魔网。你是否有时间去调查一下？"}
D.Quests[47810]={Title="阴暗的梦",Objectives="在翡翠巨龙圣地击杀萨拉斯·维索恩。",Description="翡翠巨龙圣地的古树正在梦境中遭受折磨。伊瑟拉已经不在了，而我分身乏术，没法亲自去调查。你能否帮我净化翡翠巨龙圣地的梦魇？"}
D.Quests[47828]={Title="疯狂回忆"}
D.Quests[47835]={Title="命运之手",Objectives="到刃拳海湾和前往埃索达的护卫汇合。"}
D.Quests[47844]={Title="疯狂回归"}
D.Quests[47851]={Title="封印命运：荣誉印记"}
D.Quests[47853]={Title="侧翼合击",Objectives="关闭3个军团传送门。",Description="我会指挥法瑞娅的副官，然后我们一起护送维伦前往知识桂冠。他的任务决不能失败。$b$b我们面临着一个老对手，一个圣光军团对阵了无数次的对手。塔尔加斯会想办法拦住我们，阻止我们撤退。$b$b你绝对不能让他们得逞。弄清楚他的部队是如何过来的，并将其阻断。我们最需要的是时间，杀进去然后再撤出。$b$b我们都指望你了。"}
D.Quests[47854]={Title="大主教的愤怒",Objectives="干扰阿尔诺花园中的军团部队。",Description="军团所到之处，暴力总是不可避免。$b$b<图拉扬举起了剑，表情严肃。>$b$b他们拦在了我们和维伦之间。除非我们先发制人，否则他们一定会找到他。现在还不是撤退的时候。$b$b团结一致，我们就可以在他们的部队中散布混乱。"}
D.Quests[47855]={Title="原本假如",Objectives="见证维伦的记忆。",Description="<维伦说话的同时仍然盯着雕像。>$b$b数千年之前，当我还年轻的时候，我做出了一个选择。$b$b这个选择让我的世界灰飞烟灭。这个选择导致我的人民被迫流亡。这个选择让我和我挚爱的兄弟永远分离。$b$b<维伦摇了摇头。>$b$b我不能离开，现在还不行。在我好好反思之前，我是不会离开的。"}
D.Quests[47856]={Title="穿越宇宙",Objectives="消灭塔尔加斯。",Description="塔尔加斯。他曾经是我的盟友、朋友。$b$b离开阿古斯的时候，我还很信任他。我请求他找到那些愿意跟随我的人。$b$b我给了他所需的一切，他却背叛了我，杀害我的追随者。$b$b我不知道他内心深处的这种仇恨从何而来，但他的阴谋迫使我的人民从一个世界不断逃向另一个世界。他穿越宇宙不断追杀我们。$b$b这一切必须到此为止，$n。塔尔加斯必须死。"}
D.Quests[47858]={Title="安保措施：启动"}
D.Quests[47864]={Title=" 封印命运：额外的荣誉印记"}
D.Quests[47865]={Title=" 封印命运：成堆的荣誉印记"}
D.Quests[47867]={Title="海上潜行",Objectives="与女伯爵莉亚德琳谈谈以启航前往埃索达。",Description="德莱尼人打造了一搜飞船，可以把我们安全地送到阿古斯。就在我们说话的时候，他们正在秘蓝岛聚集进攻部队。\n\n我们会从海上过去加入他们的队伍。燃烧军团肯定会盯着他们世界的入口。我们必须出其不意。\n\n你准备好了之后就跟我说。"}
D.Quests[47882]={Title="魔法的储存",Objectives="稳定8个不稳定的能量导体。",Description="我有一个主意。这个构造体对我们有用。我们只需要把它唤醒就好。$b$b我们曾经把巨大的能量存储在遍布学宫的导体之中。它们仍然可以运作，但也仅此而已。$b$b拿着这个。$b$b<伊米拉递给你一个闪闪发光的水晶。>$b$b它可以造成小型的魔法爆裂，帮助稳定不稳定的能量导体。我想存的能量应该可以足够用于8个导体。$b$b稳定几个导体后，我们应该就可以访问整个网络了。"}
D.Quests[47883]={Title="最漫长的守望",Objectives="唤醒守门人。",Description="还好我们找了两种能量源。即使这些导体激活了，构造体还是没有反应。$b$b它可能有很长一段时间没被启动过了，也许跟玛凯雷在阿古斯上方飘浮的时间一样久。$b$b它守卫的时光多么漫长而孤独。$b$b<伊米拉看着构造体，沉默了片刻。>$b$b去吧，把它刺激一下，再加上一点魔法的爆发，应该就会起作用了。"}
D.Quests[47889]={Title="代言人的召唤",Objectives="在克罗库营地与麦格尼见面。",Description="麦格尼叫你到克罗库营地和他汇合。他觉得他发现的那些东西可以帮我们消灭燃烧军团的无尽大军。\n\n想要结束这场战争，我们就必须要利用一切能利用到的优势。你应该找到他的下落。",CompletionLog="到克罗库营地与麦格尼见面。"}
D.Quests[47890]={Title="折磨的幻象",Objectives="激活圣石，和麦格尼一起观看幻象。",Description="来到阿古斯之后，我一直听到低语声。就像艾泽拉斯的低语一样，只不过……不是她的声音。\n\n我很确定，阿古斯的泰坦想要和我们取得联系！\n\n破碎者在附近藏有一个圣物。哈顿说他们是就是从那里听到低语的……我想它可能与阿古斯本身有着某种联系！\n\n就在这个房间。看看我们能发现什么东西。"}
D.Quests[47891]={Title="坏消息",Objectives="返回维迪卡尔与图拉扬会面。",Description="艾泽拉斯送我们到这里来是对的，$n。我们必须阻止萨格拉斯的计划，否则最后我们可能连艾泽拉斯这个家都没有了。$B$B你应该回到图拉扬那里，把你看到的情况告诉他。我会呆在这里，看看能否找到其他能给我们提供帮助的东西。",CompletionLog="向维迪卡尔的图拉扬复命。"}
D.Quests[47892]={Title="进攻堡垒",Objectives="前往命运角。",Description="我们已经在纳斯拉克斯要塞附近稳固了阵地。那应该是燃烧军团在阿古斯重要的军事要塞之一。\n\n立即对其发动猛烈攻击，这可能是我们扭转战场形势的唯一机会。",CompletionLog="与命运角的图拉扬汇合。"}
D.Quests[47895]={Title="伯特的机器人",Objectives="在宠物对战中击败伯特。",Description="如果我要清理诺莫瑞根，就必须准备好面对各种各样的老鼠、蟑螂，可能还有可怕的变异鼠蟑。\n\n我想说的是，我得测试这些机器人！需要进行实地检测才行！\n\n你的宠物准备好进行代码审查了吗？"}
D.Quests[47904]={Title="保卫真正的未来",Objectives="在场景战役“克罗米之死”中一次性阻止来自黑曜石、红玉、碧蓝和翡翠巨龙圣地的攻击。",Description="我知道你在想什么，$n。我可不是因为怕死才请你帮忙的。\n\n我请你帮忙是因为，我不应该这么死。我确实会死——我早就预见到了！但我的死期还早着呢。而且，为了私人原因而扰乱时间流——这违反了我们青铜龙军团的宗旨。\n\n让我们阻止对全部四座巨龙圣地的攻击。这应该管用。"}
D.Quests[47906]={Title="克罗米之死",Objectives="在场景战役“克罗米之死”中一次性阻止针对克罗米的全部八次攻击。",Description="看来我们得阻止针对我的全部八次攻击，而且要在十五分钟内完成。\n\n就算是对我来说，这段时间也不算多。\n\n可要是还有人能够做到的话，那就是我们了。你准备好了吗，$n？"}
D.Quests[47953]={Title="分选者泰瑞克"}
D.Quests[47967]={Title="阿古斯套羊手",Description="如果没有我们的岩羊，即使面对最低级的军团小队，我的战士也毫无胜算。如果你可以抓几头带回来，那么我的战士就能更好地保护人民了。"}
D.Quests[47986]={Title="过往的伤痕",Objectives="找到一个符咒阵列、一件守备官装甲和一枚审判核心。",Description="圣光军团的战争机甲已在阿古斯获得过无数胜利。这些机甲虽然力量强大，但并非所有加入战斗的机甲都能平安归来。\n\n我对这部机甲所做的调整应当能为我们提供所需的优势，但我目前仍然缺少几个关键的组件。\n\n纳斯拉克斯还残留着过往战斗的残迹，我们可以加以利用。如果你找到我所需要的组件，军团就将再次承受我们的怒火。"}
D.Quests[47987]={Title="预防措施",Description="军团的邪恶无穷无尽。每打赢一场战斗，每攻占一个世界，都会为他们的战争机器贡献更多灵魂燃料。\n\n他们还没腐化这座要塞里所有阵亡的战士，但那恐怕也只是个时间问题。拜托，请带着这枚护符进入要塞，用它净化你所遇到的尸体。\n\n他们的命运不应如此悲惨。"}
D.Quests[47988]={Title="混沌理论",Description="虽然力量强大、数量众多，但即使是燃烧军团也需要秩序。扰乱他们的秩序……他们就会化为乌合之众。\n\n计划很简单。让他们的军队陷入混乱，胜利就属于我们了。"}
D.Quests[47989]={Title="末日使者",Objectives="击杀赫拉迪卡夫人和妖女阿波崔丝。",Description="我们发现了一个大好机会。\n\n我们的侦察兵在西部的邪能之池中发现了两个破坏魔女祭司，她们正在强化军团的战争物资。\n\n萨格拉斯的近臣从不离开安托鲁斯的高墙。如果能干掉她们，我们也许可以在那些最接近黑暗泰坦的人群中间散播恐慌。"}
D.Quests[47990]={Title="一丝邪能",Objectives="收集一枚完美的邪能核心。",Description="我们的战争机甲就快完成了！现在只需要一股猛烈的电流就能重新激活它的系统。\n\n下面那个池子里的术士正在用邪能灌注阿古斯的碎片，以打造活化攻城武器。如果你可以带一枚回来，我们就能用它启动战争机甲的审判核心！"}
D.Quests[47991]={Title="黑暗阴谋",Description="艾瑞达极其擅长操纵遍布这个世界的邪能。那些没在制造活化武器的恶魔制造出了其他武器，例如哀伤尖塔。\n\n这些尖塔阻碍了我们的推进，就算是小型部队也无法抵达要塞主楼。我们必须拆毁一定数量的尖塔，清出一条道路后才能继续前进。"}
D.Quests[47992]={Title="正义黎明",Objectives="使用光铸战争机甲占领复仇者庭院。",Description="感谢你的努力，我们的敌人已陷入混乱，他们的防御工事也无法运作了。\n\n我们必须在尖塔底座稳住脚步，然后收紧围绕在他们指挥官脖子上的铰链。\n\n你的出色表现早已赢得了使用战争机甲的资格。通道清理完成后，我们将听从你的指挥。"}
D.Quests[47993]={Title="高塔之主",Objectives="击败领主纳斯拉克斯。",Description="作为许多年前将阿古斯献给燃烧军团的犒赏，领主纳斯拉克斯得以统治这座要塞。\n\n毫无疑问，他非常强大，但久居高位的他也日渐刚愎自用。\n\n尽可能利用他的傲慢和战争机甲的火力。我们很快就要突袭庭院了！",CompletionLog="在维迪卡尔与图拉扬见面。"}
D.Quests[47994]={Title="构筑联结"}
D.Quests[47995]={Title="光明正大",Objectives="找到“神射手”巴拉特、大守备官索沃斯和剑圣特拉蒙。",Description="我的士兵们还在战场上，$n。$b$b我需要你去找到巴拉特、索沃斯和特拉蒙。军团突然出现在我们面前时，他们正在为维伦清理这片地区。$b$b去通知他们，现在的命令是立即回到先知身边。$b$b已经没时间小心翼翼了。一小股敌人正挡在我们之间。不必手下留情。$b$b圣光保佑你。"}
D.Quests[48002]={Title="补给有限",Description="你好，$n。很高兴能够再次见到炼金术师同行。$b$b我一直在为我们的营地提供对付恶魔所需的药水，但我的库存最近总是不太足。侦查兵们平时出去之后，都会带着空瓶子回来，但最近回收到的却很少。$b$b我已经在尽可能地重复利用了，所以你瞧，这些瓶子对我非常重要。如果你愿意去野外把我的瓶子找回来，我可以教你一种药水，在对抗恶魔的时候很有帮助。"}
D.Quests[48013]={Title="反追踪",Description="$n，我有没有跟你讲过我的追踪药水？我们的侦察兵用它追踪恶魔，尤其是他们的“魔犬”。$b$b那些怪物特别喜欢吞噬附近的星辰之耀，导致我们的草药库存一直无法补充。$b$b如果你能削减它们的数量，我们就不用去其他地方补充库存，那可就帮了大忙了。他们在安尼赫兰熔池附近大量徘徊。$b$b为了感谢你的帮助，我会将这种药水的配方送给你。"}
D.Quests[48016]={Title="提升炼金",Description="我看到某些经过我们营地的炼金师携带着一种有趣的饰品。我记得他们好像称之为……“炼金石”？$b$b我能感觉到那些石头散发的力量，但它们似乎被邪能污染了。这颗星球上生长的草药尤其擅长净化腐蚀。我用它来净化那些经常出现在草药里的源生萨格里特。$b$b我敢肯定，如果我们对那些石头使用净化过的萨格里特，就能够提升其中蕴藏的力量。"}
D.Quests[48021]={Title="克罗米",Objectives="与龙骨荒野的克罗米的友谊达到“时空跃迁者”级别。",Description="$n，是你吗？$b$b我相信时间线里出现了怪事。我需要你的帮助！$b$b到龙眠神殿来找我吧，就在龙骨荒野。我会亲自带你看看 。"}
D.Quests[48027]={Title="阿古斯之耀",Objectives="在阿古斯找到一个可以教你处理星辰之耀的人。",Description="<你从地上摘起那朵花。如此纯净的东西竟然还能在这颗星球上生长，真是令人惊奇。你感觉到其中弥漫出微弱的力量，随后消散殆尽。>$b$b<随着它在手中凋零，你不禁思考，在这片被圣光遗忘的土地上，是否会有人知道该如何处理这种珍贵的草药。>"}
D.Quests[48028]={Title="年轻的抵抗",Objectives="询问弗恩，了解如何处理较为鲜嫩的星辰之耀。",Description="<开始采集之后，你发现一些较为鲜嫩的花朵依然抵制你的接触，拒绝投降。也许弗恩知道该如何应对新开的花朵。>"}
D.Quests[48029]={Title="它的心",Objectives="询问弗恩，了解星辰之耀的发光根茎。",Description="<与星辰之耀打了一段时间的交道之后，你对它的根茎产生了兴趣。紧紧缠成茧形的根茎里，细小的光斑穿透裂隙照射出来，散发出莹莹微光。$b$b也许弗恩知道这种光芒是什么。>"}
D.Quests[48034]={Title="天界金矿脉结块",Objectives="在维迪卡尔上找到一个可以教你开采天界金矿脉的人。",Description="<你挖向矿石的时候，镐头发出一声巨响，一小块碎石掉落在地。按照这种速度，想从这处矿脉挖出足够的矿石，将需要花费一整天的时间。$b$b也许有人可以指导你如何正确地开采这种矿石？>"}
D.Quests[48035]={Title="更精准的角度",Objectives="和卡米尔对话，了解是否有办法提高开采天界金矿脉的效率。",Description="<看着挖掘矿脉后产生的天界金粉尘，你不禁思考，是否有办法能够防止矿脉在挖掘时碎裂。>$b$b<也许卡米尔可以和你分享一些经验。>"}
D.Quests[48036]={Title="完美精准",Objectives="和卡米尔对话，了解是否能够再提高开采天界金矿脉的效率。",Description="<虽然你已经学会如何最大限度地开采矿脉，但矿脉的核心却总是无法使用。近距离观察之下，你发现你击打的地方就是核心开裂的地方。>$b$b<看来还需要再拜访卡米尔一次，以解决这个问题。>"}
D.Quests[48037]={Title="天界金矿层结块",Objectives="在维迪卡尔上找到某个也许可以教你开采天界金矿层的人。",Description="<一开始，你以为矿石表层是镜面，反射着头顶上的漫天繁星。挖下一大块之后，你发现原来矿石本身的质地便如星光一般。>$b$b<也许维迪卡尔上有人可以指导你如何更高效地开采这种矿层。>"}
D.Quests[48038]={Title="别闷头下镐",Objectives="与卡米尔对话，了解如何从天界金矿层中开采更多矿石。",Description="<虽然你已经学会了暴露矿石，但大型结块似乎依然牢牢地嵌在周围的岩石中。开采这种矿石也许无法得到你所需要的纯净天界金。>$b$b<也许卡米尔可以告诉你该如何挖掘矿层中的这种矿石。>"}
D.Quests[48039]={Title="平衡力度",Objectives="与卡米尔对话，了解如何从天界金矿层中开采更多矿石。",Description="<逐渐深入矿层底部之后，你只能找到小块矿石和碎片。虽然总和起来的话，数量应该够用。>$b$b<卡米尔也许有办法防止这种情况的发生。>"}
D.Quests[48040]={Title="被污染的碎皮",Objectives="在维迪卡尔上找到某个也许可以教你剥制恶魔皮革的人。",Description="<当你开始小心翼翼地剥皮时，你发现尸体的腐烂很快污染了皮毛。>$b$b<剥下皮后，你只能使用其中一小部分的皮革，而且气味非常难闻。也许维迪卡尔上有人知道这种恶臭皮毛的事情。>"}
D.Quests[48041]={Title="大块皮革",Objectives="和恩斯特拉对话，学习更高效的恶魔皮革剥离方法。",Description="<虽然你的剥皮速度快多了，但还是有很多皮革在剥下前被污染。>$b$b<恩斯特拉也许知道该如何在皮毛被污染前剥离出更多皮革。>"}
D.Quests[48042]={Title="操作顺序",Objectives="与恩斯特拉对话，学习更高效的阿古斯野兽解剖法。",Description="<毛皮的数量充裕多了，但你只来得及收集到少数未被污染的牙齿和爪子。>$b$b<由于不知道该如何提高牙齿和爪子的收集效率，你还需要再找维迪卡尔的恩斯特拉谈一谈。>"}
D.Quests[48053]={Title="重压船锚",Objectives="将一箱邪能页岩带给暴风城港口的沃尔科特·桑顿。",Description="$n，希望你能帮我一个小忙。暴风城港口的海军舰队订购了大量邪能页岩，用于船舰的补给。$b$b我现在正忙着指挥采集工作，而我的信使也都没回来。不知道你是否愿意帮我把这批货送去给他们？$b$b我听说达拉然的灰牙之地里开有通往暴风城的传送门，所以这段路应该不会太漫长什么的。"}
D.Quests[48054]={Title="重压船锚",Objectives="将一箱邪能页岩带给锈水港的克鲁达·雷手。",Description="$n，希望你能帮我一个小忙。锈水港的海军舰队订购了大量邪能页岩，用于船舰的补给。$b$b我现在正忙着指挥采集工作，而我的信使也都没回来。不知道你是否愿意帮我把这批货送去给他们？$b$b我听说达拉然的风行者圣殿里开有通往奥格瑞玛的传送门，所以这段路应该不会太漫长什么的。"}
D.Quests[48055]={Title="天界金之力",Objectives="制作一件天界金胸甲。你可以通过阿古斯的矿石开采、与其他玩家交易或从拍卖行得到材料。",Description="看来我的护甲似乎引起了你的兴趣。这是由阿古斯最高级的材料：天界金打造的。我其实最擅长制作胸甲。$b$b我可以教你制作，但恐怕你必须自带材料。我们的矿石存量太少，而且不能平白消耗。$b$b但这是所需材料的清单，以便你去收集……"}
D.Quests[48056]={Title="严厉的月亮",Objectives="帮助霍巴特在达拉然城内校准原型款减重便鞋。",Description="我之前思考着，要如何让大家在阿古尔还是那什么的星球上面自由行动呢？因为我觉得那里的重力应该和我们的不一样。于是我想出了一款装置，可以装在你的鞋子或者蹄子，或者你要在那里穿的其他东西上面。$b$b后来我听说，那个星球的重力……和我们这儿完全一样！$b$b不管如何，我想，我可以先把原型款做出来。你愿意搭把手吗？也许等我们做出来以后，你可以把它卖给孩子们什么的。"}
D.Quests[48065]={Title="外星探索",Objectives="在你的地图上标记的位置使用电离地理记录仪。完成后回去找蒂迪。",Description="$n，我听说你已经去过天上那颗巨大的绿色星球了。据说那里也是恶魔肆虐。$b$b我在想，我们也许可以为它再组装一台虫洞发生器。让那颗星球上的快速移动变得更加容易。$b$b问题是我们必须获得地形的数据。虽然我愿意亲自去，但是，呃……我必须留在这里看店。不能把店铺留给这些蠢货。$b$b拿上这个，去给我记录点数据回来，行不？"}
D.Quests[48066]={Title="款待同胞",Objectives="前往莫高雷的雷霆崖找贝恩·血蹄。",Description="为了欢迎至高岭牛头人访问雷霆崖，我们策划了一场盛大的宴会。这将是他们第一次造访卡利姆多。我跟他们的酋长通过信……很期待能与她面对面交流。\n\n你会来莫高雷加入我们吗？他们一定很乐意见到你这位协助他们对抗燃烧军团的老熟人。",CompletionLog="前往莫高雷的雷霆崖找贝恩·血蹄。"}
D.Quests[48067]={Title="雷霆崖的阴影",Description="一股黑暗力量降临到了我们头上。我不相信这是高岭牛头人策划的。\n\n外面的噪音有点耳熟，这让我很不安。难道是……\n\n不！上古之神的爪牙进攻了！我们必须为雷霆崖而战，$n！"}
D.Quests[48069]={Title="钳子在呼唤",Objectives="去达拉然找钳工蒂迪。",Description="$n，达拉然的钳工蒂迪正在找你。你最好去看看她近期的成果。据说挺高端的。"}
D.Quests[48074]={Title="将我笼罩",Objectives="前往阿尔诺花园，找回凯拉的光纹织布机。",Description="赶到泽尼达尔的时候，我丢失了一件珍贵的工具，我的光纹织布机。没有它，我为盟友制作强力物品就得耗费更长的时间。$b$b但你很强大，比我强多了。也许你可以帮我个忙。如果你碰巧路过阿尔诺花园，是否可以帮忙找回我的织布机？$b$b届时我将非常乐意与你分享我的光纹布纺织技术。"}
D.Quests[48075]={Title="绚丽的钥匙",Objectives="前往沃雷尔的家，使用从天界金中选矿获得的六种宝石打开他的箱子。找到沃雷尔的珠宝加工书，并带回维迪卡尔交给他。",Description="$n，听说你是个珠宝匠。我也是个切割大师，但我很怕我的设计会落入军团之手。$b$b我匆忙离开老家，原本还想着回去，但如今恐怕是没这个机会了。你瞧，我将我最珍贵的宝物——一本珠宝加工设计书落在家里了。$b$b但你不一样，你很强大，你可以一路披荆斩棘前往我的老家，找回我的书！$b$b不过我用一个特殊的箱子把它锁起来了，需要用这片大地上的宝石去解锁。每种宝石都需要一颗，才能打开箱子。"}
D.Quests[48076]={Title="冠冕成就",Objectives="为沃雷尔打造一顶天界王冠。你可以通过采集阿古斯的矿石来选矿、与其他玩家交易、或者从拍卖行得到材料。",Description="差点永远失去这本书后，我意识到我不该将这些知识保存在一个地方。我愿意将它们传授给你，$n。$b$b我最近的几项设计尤其令我自豪。我将它们称为天界王冠。每顶皇冠都使用不同的宝石组合，从而实现不同的强大效果。$b$b我来教你怎么加工，以及不同的宝石组合如何获得不同的效果。"}
D.Quests[48078]={Title="平衡力",Description="很久以前，我可以用这片大地上的野兽制作出精美的物品。但后来，燃烧军团的降临灭绝了所有那些神奇的动物。$b$b现在我只能使用它们被污染的皮毛来为盟友制作护甲。但我还是想出了净化污秽的办法。$b$b我们所使用的布料由灌注着圣光能量的线织成。我发明了一种油，搭配布料可以净化皮革，以供使用。$b$b拿上我的油，自己去试试吧。"}
D.Quests[48079]={Title="返回至高岭",Objectives="前往至高岭的雷霆图腾找梅拉·高岭。",Description="灵魂行者黑角还有危险。他与梅拉已经回到了至高岭，但我相信他们仍然需要帮助。\n\n让我们前往雷霆图腾，尽可能治愈黑角。也许我们的努力能加强我们人民之间的联系。",CompletionLog="前往至高岭的雷霆图腾找梅拉·高岭。"}
D.Quests[48081]={Title="飘浮的废墟",Objectives="前往玛凯雷。",Description="我们本就知道燃烧军团是个可怕的敌人，但最近的事件表明，我们的力量还不够强大，难以支持下去。我们付出了如此巨大的代价，这样的关键时刻已不容失败。$b$b我知道我那古老的家乡玛凯雷有一件圣物，可能就是我们的出路。我们必须让维迪卡尔离开阿古斯星球表面，前往悬浮在上空的废墟。$b$b也许我们能在那里找到我们急需的出路。"}
D.Quests[48091]={Title="背弃者瓦加斯"}
D.Quests[48095]={Title="黑暗实验"}
D.Quests[48096]={Title="核心机制"}
D.Quests[48097]={Title="守门人的评价：机智"}
D.Quests[48098]={Title="花园害虫"}
D.Quests[48099]={Title="敌意回响"}
D.Quests[48100]={Title="保卫玛凯雷"}
D.Quests[48101]={Title="公开演讲"}
D.Quests[48102]={Title="鳞片样本"}
D.Quests[48105]={Title="同行评议"}
D.Quests[48106]={Title="不留情面"}
D.Quests[48107]={Title="启迪印记",Objectives="返回维迪卡尔，放置启迪印记。",Description="这件圣物太过强大，不能放在外面。$b$b我们必须立即将其送回维迪卡尔。先知明白该怎么做。$b$b我非常感谢你，$n。没有你的话，这一切都不会成功。夸拉姆绝不会让我靠近印记。也许某天，我可以跟你讲讲那个故事。"}
D.Quests[48175]={Title="藏匿虚空"}
D.Quests[48185]={Title="圣墓的阴影",Objectives="在苍穹圣墓与灵魂行者灰天见面。",Description="黑角说过，有一个结界保护着天角部族的土地。据说它就位于苍穹圣墓附近。这个“黑暗之王”曾经在那里出现过。\n\n去那里找我吧，$n。我会告诉你该如何走进一位伟大的天角英雄的回忆。",CompletionLog="在苍穹圣墓与灵魂行者灰天见面。"}
D.Quests[48190]={Title="胡恩的高岭",Objectives="在雪盲台地与灵魂行者灰天见面。",Description="我们激活结界的任务有了一些进展，但还有更多事情要做。\n\n我感觉黑角正在挣扎。虽然他已经全力反抗，却仍一步步滑向深渊。如果这个“黑暗之王”出现在我们的世界，我们的朋友恐怕就没救了。\n\n黑角提到过，雪盲台地的某个地方还有一个结界。去那里找我吧，我或许能指引你进入另一段回忆。",CompletionLog="在雪盲台地与灵魂行者灰天见面。"}
D.Quests[48192]={Title="焦油喷吐者"}
D.Quests[48199]={Title="灼燃之心",Objectives="使用导航控制台前往安托兰废土。",Description="泽拉的死是一次沉重的打击，对图拉扬来说尤其如此。但即使是圣光之母也不能强迫我们接受命运。\n\n如果伊利丹换一种方式拒绝她就好了……但我其实也曾经面对过纳鲁强加给我的选择。\n\n我们不能为此而分心，我们的使命还在等待我们。现在圣光军团的生还者加入了我们，我们可以加紧攻击了。\n\n我们要在安托兰废土站稳脚跟，这样才能攻击燃烧王座。时候到了，绝不能让萨格拉斯的邪恶计划成功！"}
D.Quests[48200]={Title="立足之地",Objectives="前往安托兰废土，放置光铸道标。",Description="我和奥蕾莉亚以前侦察过这片地区，当时身边还有几个精英战士。我们在目前位置的两侧扎下了营地，但我担心他们会受到猛烈攻击，需要援助。$b$b我们的首要任务是在维迪卡尔正下方设置一个传送道标。我们可以从那里前往两个作战前线。$b$b你准备好前往地面的话，就与罗姆尔谈一谈。"}
D.Quests[48201]={Title="增援圣光据点",Objectives="与圣光据点的奥蕾莉亚谈一谈。",Description="既然我们已经站稳脚跟，就可以与战场上的士兵汇合了。$b$b我们在南面有座圣光军团的营地，燃烧军团把他们最强的战士储藏在那附近，并让他们处于某种静滞状态。$b$b奥蕾莉亚去侦察那片区域了。找到她，看看她收集到了什么情报。"}
D.Quests[48202]={Title="支援隐匿洞穴",Objectives="与隐匿洞穴的伊利丹谈一谈。",Description="有了你建立的据点，我们就能与战地特工接洽了。$b$b我们上次到这里来执行任务时，在东北方建立了一个堡垒，目前应该还能起到防御的作用，但战场局势瞬息万变。$b$b伊利丹已经过去查看形势了。我建议你也过去，看看他需不需要你帮忙。"}
D.Quests[48203]={Title="燃烧王座",Objectives="在安托兰废土上方使用执政团之冠打开通往安托鲁斯的道路。",Description="时机成熟了，$n，可以开始攻打安托鲁斯了。我们多年的奋斗，以及亲友所作出的牺牲，终于让我们走到了今天。$b$b我们会用圣光裁决者轰开这座诅咒堡垒的高墙，踏平他们的权力中心。我们会成为燃烧军团的终结者。$b$b你在这场战争中居功至伟，这份荣耀应该属于你。激活执政团之冠吧，让我们一起完成这份使命。"}
D.Quests[48230]={Title="过去的碎片",Objectives="将发光的钥匙碎片交给法瑞娅队长。",Description="<你的目光被一块散发着微弱光芒的水晶碎块所吸引。检查碎块后，你发现它的表面上还残留着镌刻的符文。\n\n这块碎片似乎与圣光军团用来为军械供能的阿古尼特水晶类似。这块水晶会不会属于那个很久以前，为逃出阿古斯而战的艾瑞达？\n\n也许法瑞娅队长知道更多关于这块水晶的情况。>"}
D.Quests[48231]={Title="执政团之座：执政团护甲",Objectives="获得圣光护甲并将它交给档案员伊欧纳。",Description="这把重铸的钥匙可以打开执政团之座里面的军械库。\n\n锁在里面的是执政团护甲。这套护甲是在萨格拉斯毁灭我们的世界之前打造的。绝不能让虚空的势力偷走这套护甲。\n\n拿到护甲后，请交给档案员伊欧纳。他把我们最珍贵的圣物都存放在这条路尽头的洞窟里。他一定会很乐意接受这套护甲。"}
D.Quests[48261]={Title="重铸能量",Objectives="获得大量枝蔓晶簇。",Description="我是用太古阿古尼特水晶打造的这把钥匙。不幸的是，现在剩下的水晶都被用在圣光军团的防御工事上了。\n\n唔……枝蔓晶簇大概也能行。玛凯雷的精英经常用它们来给简易的设备供能。如果还可以找到完整的城市废墟，那么我猜那里的堕落法师或破碎者身上可能还带着一些。 \n\n当然，我们需要许多这种晶簇才能重铸钥匙。看来又到你出马的时候了。"}
D.Quests[48271]={Title="找回碎片",Objectives="从执政团之座周围的虚灵身上找到丢失的钥匙碎片。",Description="你找到的只是一块钥匙碎片，恐怕其他碎片落在了你说的那些虚灵生物手上……就是那些“影卫虚灵”。\n\n我们必须把碎片全都找回来。执政团之座内外的影卫虚灵首领和副官手上很可能就有这些碎片。\n\n去把那些钥匙碎片找回来，$n……无论采取什么手段。"}
D.Quests[48272]={Title="恐惧幻象",Objectives="与麦格尼一起见证阿古斯的幻象。",Description="我做到了，$G小伙子:丫头;。我又联系上他了！ \n\n哦，但真的好痛苦。好痛苦！他的情况不妙，极其不妙！\n\n你必须和我一起倾听才能明白。"}
D.Quests[48273]={Title="代言人的倾听",Objectives="与克罗库营地的麦格尼见面。",Description="麦格尼又要你去克罗库营地了。他在尝试联系阿古斯方面似乎取得了新进展。\n\n我建议你立即去见他。他的上一个幻象预言了阿格拉玛的到来，我们对于萨格拉斯的计划还所知甚少。",CompletionLog="与克罗库营地的麦格尼见面。"}
D.Quests[48277]={Title="代言人的寻找",Objectives="与克罗库营地的麦格尼见面。",Description="我们的部队已经做好战斗准备，但我们依然不知道艾欧娜尔的灵魂在哪里。\n\n你最好立即去见麦格尼，看看我们是否还有机会找到她。如果她已经堕落，那么我们召集再多人手也不可能对抗萨格拉斯。",CompletionLog="与克罗库营地的麦格尼见面。"}
D.Quests[48280]={Title="另一位的幻象",Objectives="与麦格尼一起见证阿古斯的幻象。",Description="无论现在想要联系我们的人是谁，都有可能带来寻找艾欧娜尔所需的线索。\n\n我们必须立即去看看情况！"}
D.Quests[48284]={Title="战场死神"}
