D.Quests[48286]={Title="水晶的用途"}
D.Quests[48287]={Title="悲伤收割者"}
D.Quests[48288]={Title="安托兰统帅议会",Objectives="击败安托鲁斯，燃烧王座的安托兰统帅议会。",Description="燃烧军团花费了一万多年的时间策划对艾泽拉斯的入侵。击败他们的首领，让他们再也无法威胁到我们的世界。"}
D.Quests[48292]={Title="猎魂者",Objectives="击败安托鲁斯，燃烧王座的猎魂者伊墨纳尔。",Description="伊墨纳尔是扭曲虚空中有史以来最致命的赏金猎人。找个地方把他解决掉。"}
D.Quests[48293]={Title="燃烧的女巫会",Objectives="击败安托鲁斯，燃烧王座的破坏魔女巫会。",Description="即使是泰坦也无法忍受他们的折磨。把破坏魔女巫会干掉吧。"}
D.Quests[48294]={Title="寂灭者",Objectives="击败安托鲁斯，燃烧王座的寂灭者阿古斯。",Description="阿古斯是萨格拉斯消灭万物存在的终极手段。为了现在和将来的所有生命，请消灭寂灭者。"}
